package com.nimbusbill.customer.entity; import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="customer_pricing_assignments") public class CustomerPricingAssignment{@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(optional=false) @JoinColumn(name="customer_id") private Customer customer;@ManyToOne(optional=false) @JoinColumn(name="plan_id") private PricingPlan plan;@Column(name="billing_account_id") private UUID billingAccountId;@ManyToOne @JoinColumn(name="product_id") private PaymentProduct product;@ManyToOne @JoinColumn(name="superseded_by") private CustomerPricingAssignment supersededBy;@Column(name="effective_from",nullable=false) private LocalDate effectiveFrom;@Column(name="effective_to") private LocalDate effectiveTo;@Column(nullable=false) private boolean active;@Column(name="created_at",nullable=false) private Instant createdAt;@PrePersist void create(){createdAt=Instant.now();}public UUID getId(){return id;}public Customer getCustomer(){return customer;}public void setCustomer(Customer v){customer=v;}public PricingPlan getPlan(){return plan;}public void setPlan(PricingPlan v){plan=v;}public UUID getBillingAccountId(){return billingAccountId;}public void setBillingAccountId(UUID v){billingAccountId=v;}public PaymentProduct getProduct(){return product;}public void setProduct(PaymentProduct v){product=v;}public CustomerPricingAssignment getSupersededBy(){return supersededBy;}public void setSupersededBy(CustomerPricingAssignment v){supersededBy=v;}public LocalDate getEffectiveFrom(){return effectiveFrom;}public void setEffectiveFrom(LocalDate v){effectiveFrom=v;}public LocalDate getEffectiveTo(){return effectiveTo;}public void setEffectiveTo(LocalDate v){effectiveTo=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}}
